import json

from django.db import transaction
from django.http import JsonResponse

from .models import Order, OrderLine
from .tasks import send_order_confirmation


@transaction.atomic
def create_order(request):
    order = Order.objects.create(status="pending")
    for item in json.loads(request.body)["lines"]:
        OrderLine.objects.create(
            order=order,
            product_id=item["product_id"],
            quantity=item["quantity"],
        )
    send_order_confirmation.delay(order.id)
    return JsonResponse({"id": order.id}, status=201)

from celery import shared_task

from .models import Order, OrderLine
from .services import reserve, send_confirmation_mail


@shared_task
def send_order_confirmation(order_id):
    order = Order.objects.get(pk=order_id)
    send_confirmation_mail(order)


@shared_task
def reserve_stock(line_id):
    line = OrderLine.objects.get(pk=line_id)
    reserve(line.product_id, line.quantity)

