from .tasks import reserve_stock, send_order_confirmation


@transaction.atomic
def create_order(request):
    order = Order.objects.create(status="pending")
    for item in json.loads(request.body)["lines"]:
        line = OrderLine.objects.create(
            order=order,
            product_id=item["product_id"],
            quantity=item["quantity"],
        )
        transaction.on_commit(lambda: reserve_stock.delay(line.id))
    transaction.on_commit(lambda: send_order_confirmation.delay(order.id))
    return JsonResponse({"id": order.id}, status=201)

import json
from unittest import mock

from django.test import TestCase


class CreateOrderTests(TestCase):
    @mock.patch("orders.views.reserve_stock")
    @mock.patch("orders.views.send_order_confirmation")
    def test_dispatches_after_commit(self, confirm, reserve):
        body = {"lines": [{"product_id": 7, "quantity": 2}]}
        with self.captureOnCommitCallbacks(execute=True):
            response = self.client.post(
                "/orders", json.dumps(body), content_type="application/json"
            )
        confirm.delay.assert_called_once_with(response.json()["id"])
        reserve.delay.assert_called_once()
